    match goal with |- evt _ _ (MS ?R _ _ _ _ ?mm _) => let t1 := rv_reg R 11 in let t0 := rv_reg R 10 in
      lazymatch t1 with Z_to_bv 64 (sh8 (161760 + 8 * ?idx)) =>
        replace t0 with (Z_to_bv 64 (161760 + 8 * idx)) by (f_equal; lia);
        let PSH := fresh "PSH" in let RD := fresh "RD" in
        pose proof (POWSH idx ltac:(lia)) as PSH;
        pose proof (pow10u_read mm idx ltac:(assumption) ltac:(lia)) as RD; unfold POW10U_TBL in RD
      end end;
    st1; st1; let K := fresh "KT" in brp K; st1.
