    match goal with |- evt _ _ (MS ?R _ _ _ _ _ _) => let t := rv_reg R 10 in
      lazymatch t with Z_to_bv 64 (bv_unsigned (Z_to_bv 64 ?x) * 2^3 + 164224) =>
        replace t with (Z_to_bv 64 (161760 + 8 * (x + 308)))
          by (symmetry; apply Z_to_bv_eqm; rewrite Z_to_bv_unsigned; unfold bv_wrap; change (bv_modulus 64) with (2^64);
              rewrite <- (Z.add_mod_idemp_l _ 164224 (2^64)), Z.mul_mod_idemp_l, Z.add_mod_idemp_l by lia; f_equal; lia)
      | Z_to_bv 64 (?x * 2^3 + 164224) =>
        replace t with (Z_to_bv 64 (161760 + 8 * (x + 308))) by (f_equal; lia)
      end end;
    fin_tbl POWSH; fin_close.
